    filter?: string;
    /**
     * How `filter` is written:
     * - `'case'` (default): `COUNT(CASE WHEN filter THEN column END)`, in every database;
     * - `'filter'`: `COUNT(column) FILTER (WHERE filter)`, PostgreSQL and SQLite 3.30+ only, a few percent faster on PostgreSQL.
     */
